 page.evaluate("""async()=>{const {heightAt}=await import('/src/terrain.js');window.floorAt=heightAt;window.setup=(cls='warrior',branch=null)=>{const api=window.__AETHERWILD__,e=api.engine,p=api.createPlayer(cls);p.level=20;p.branch=branch;api.startGame(p);e.paused=true;e.player.mana=999;e.world.colliders=[];e.feetY=heightAt(0,-14);e.fallPeak=e.feetY;e.camera.position.set(0,e.feetY+1.75,-14);e.grounded=true;e.yaw=0;e.pitch=-.4;e.camera.rotation.set(e.pitch,0,0);e.camera.updateMatrixWorld();for(const m of e.world.monsters){m.alive=false;m.deathAge=9;m.group.visible=false;m.respawnAt=1e9;}return e;};window.place=(m,x,z,y=heightAt(x,z))=>{Object.assign(m,{alive:true,hp:10000,x,z,homeX:x,homeZ:z,freeze:999,aggro:false,island:{x,z,y,r:50}});m.group.visible=true;m.group.position.set(x,y,z);return m;};}""")
 page.evaluate("""()=>{const e=setup('ranger');e.paused=false;}""");page.wait_for_function('window.__AETHERWILD__.engine.locked');page.mouse.down();page.wait_for_function('window.__AETHERWILD__.engine.bowCharge>.99')
 page.evaluate("""()=>{const e=window.__AETHERWILD__.engine;e.paused=true;e.movement(0);e.weapon.updateMatrixWorld(true);const p=e.weapon.getWorldPosition(new e.camera.position.constructor()).project(e.camera);if(p.x<=0||p.x>1)throw Error('bow not on screen right');const hand=e.weapon.userData.drawHand.getWorldPosition(new e.camera.position.constructor()).project(e.camera);if(hand.x<=0)throw Error('hand on wrong screen side');}""")
