 page.evaluate("""()=>{const e=setup('ranger','shadow'),V=e.camera.position.constructor;e.camera.position.set(0,101.1,-18);e.feetY=99.35;const targets=e.world.monsters.slice(0,3);place(targets[0],0,-24,100);place(targets[1],0,-43.5,100);place(targets[2],0,-64,100);e.camera.rotation.set(0,0,0);e.camera.updateMatrixWorld();e.skill(4);if(e.arrowSkill.bounceRange!==20)throw Error('old range');e.beginBow();e.drawStartedAt=performance.now()-1300;e.releaseBow();for(let i=0;i<600;i++)e.updateProjectiles(1/120);if(targets[0].hp===10000||targets[1].hp===10000||targets[2].hp!==10000)throw Error('twenty-metre chain boundaries');}""")
 passed('real assassin projectile bounces across 19.5 metres and rejects the next enemy 20.5 metres away')
 page.evaluate("""()=>{const e=setup('ranger');const target=place(e.world.monsters[0],0,-24);e.camera.lookAt(e.monsterCenter(target));e.camera.updateMatrixWorld();e.skill(1);e.beginBow();e.drawStartedAt=performance.now()-1300;e.releaseBow();for(let i=0;i<160;i++)e.updateProjectiles(1/120);const fx=e.fx.items.find(x=>x.spellKind==='frostBurst');if(!fx||fx.group.children[0].geometry.type!=='SphereGeometry'||fx.group.position.y<=target.group.position.y+.2)throw Error('explosion not at impact point');e.updateEffects(.18);const ys=fx.group.children.slice(2).map(o=>o.position.y);if(Math.min(...ys)>-1||Math.max(...ys)<1)throw Error('not spherical');}""")
