 # Both centre effects must start at a damage step and last eight actual render updates.
 for index,kind in [(3,'meteorZone'),(4,'arcaneZone')]:
  report=page.evaluate("""({index,kind})=>{const e=setup('mage','archmage');e.player.mana=999;e.skill(index);const c=e.groundTarget(e.targetedSkill.range).point,m=place(e.world.monsters[0],c.x,c.z,c.y);e.world.update(e.time,0,e.camera.position,true);e.renderer.render(e.scene,e.camera);const before=e.fx.preparationStats.built,programs=e.renderer.info.programs.length;const start=performance.now();e.castTargetedSpell();const ms=performance.now()-start,entry=e.fx.items.find(x=>x.spellKind===kind),field=e.fields[0];if(!entry?.pooled||e.fx.preparationStats.built!==before)throw Error('cold spell construction');if(e.fx.items.some(x=>x.spellKind==='fieldImpact'))throw Error('early centre effect');e.updateCombat(field.timer-.001);e.updateEffects(.1);if(entry.impacted||m.hp!==10000)throw Error('impact before damage');e.updateCombat(.002);if(!entry.impacted||m.hp===10000)throw Error('impact not tied to damage');const burst=e.fx.items.find(x=>x.spellKind==='fieldImpact');if(!burst)throw Error('missing centre bloom');for(let i=0;i<8;i++){e.updateEffects(1/60);e.renderer.render(e.scene,e.camera);if(!e.fx.items.includes(burst)||burst.fadeAge!==0)throw Error('fewer than eight frames');}e.updateEffects(.1);if(burst.fadeAge<=0||burst.fadeAge>=.32)throw Error('no gradual fade');return {kind,ms,pooled:entry.pooled,programsBefore:programs,programsAfter:e.renderer.info.programs.length,reused:e.fx.preparationStats.reused};}""",{'index':index,'kind':kind})
  print('MEASURE '+str(report),flush=True);assert report['ms']<150,report
  page.screenshot(path=str(out/('v08-'+kind+'-impact.png')),timeout=120000)
  passed(kind+' uses a prebuilt spell; centre bloom starts with damage, remains for eight rendered frames and fades gradually')
 page.evaluate("""()=>{const e=setup('warrior','berserker');e.paused=false;window.takeoff=e.feetY;}""");page.wait_for_function('window.__AETHERWILD__.engine.locked');page.keyboard.press('Digit5');page.wait_for_function('window.__AETHERWILD__.engine.leap?.phase==="aim"&&window.__AETHERWILD__.engine.feetY>window.takeoff+7.8')
 page.evaluate("""()=>{const e=window.__AETHERWILD__.engine,c=e.groundTarget(e.targetedSkill.range).point;window.slamTargets=e.world.monsters.slice(0,2);place(slamTargets[0],c.x,c.z,c.y);place(slamTargets[1],c.x+11,c.z,c.y);if(e.cooldowns[4]!==0)throw Error('jump spent cooldown before click');}""")
 page.screenshot(path=str(out/'v08-leap-aim.png'),timeout=120000);page.mouse.down();page.mouse.up();page.wait_for_function('!window.__AETHERWILD__.engine.leap&&window.__AETHERWILD__.engine.grounded')
 assert page.evaluate('slamTargets[0].hp<10000&&slamTargets[0].freeze>0&&slamTargets[1].hp===10000&&window.__AETHERWILD__.engine.cooldowns[4]>0')
 page.screenshot(path=str(out/'v08-leap-impact.png'),timeout=120000)
