 page.evaluate("""()=>{const e=setup('warrior');e.pitch=0;e.camera.rotation.set(0,0,0);window.rushZ=e.camera.position.z;e.paused=false;}""");page.wait_for_function('window.__AETHERWILD__.engine.locked');page.keyboard.press('Digit2');page.wait_for_function('!!window.__AETHERWILD__.engine.dash');page.wait_for_function('!window.__AETHERWILD__.engine.dash')
 assert page.evaluate('Math.abs(window.rushZ-window.__AETHERWILD__.engine.camera.position.z-11)<.03')
 passed('native charged rush travels eleven metres and retains its charge/physical movement')
 report=page.evaluate("""async()=>{const e=window.__AETHERWILD__.engine;e.paused=true;const {ANIMATION_HZ,ANIMATION_STEP}=await import('/src/animation.js'),types=new Map();for(const m of e.world.monsters){const d=m.group.userData.detailCounts;if(['blackslime','basilisk','ghost','darkgolem','shadowguard','firedragon'].includes(m.type)){if(m.group.userData.designVersion!==9)throw Error('unversioned new design '+m.type);continue;}if(!d||d.ratio<2||m.group.userData.designVersion!==8)throw Error('detail not doubled '+m.type);types.set(m.type,d);if(['wolf','frostwolf','drake'].includes(m.type)){const eyes=[];m.group.userData.rig.head.traverse(o=>{if(o.name==='anatomical-eye')eyes.push(o);});if(eyes.length!==2||eyes.some(o=>o.position.x*o.userData.orbitalNormal[0]<=0||Math.abs(o.userData.orbitalNormal[0])<.35))throw Error('eye sockets not lateral');}}if(ANIMATION_HZ!==120||ANIMATION_STEP!==1/120||e.motion.tracks.length<100)throw Error('motion system not active');return {rate:ANIMATION_HZ,tracks:e.motion.tracks.length,species:types.size,minimumRatio:Math.min(...[...types.values()].map(d=>d.ratio))};}""")
 print('DETAIL '+str(report),flush=True);assert report['species']==17
